// 0: brute force + dp (60fps @ 512x288, 4.6s)
// 1: bellman-ford (slow! unproperly unrolled array access?) (<1fps @ 512x288, ~8s)
#define algorithm 0

const vec4 wall[] = vec4[](
    vec4(-5, 0, -3, 0),
    vec4(0, 0, 5, 0),
    vec4(6, 0, 8, 0),
    vec4(0, 0, 0, 5),
    vec4(0, -3, 0, -1),
    vec4(-3, -3, -3, 2),
    vec4(-3, -3, 2, -3),
    vec4( 4, -3, 8, -3),
    vec4(-8, -5, 8, -5),
    vec4(-8, -5, -8, 5),
    vec4(-8,  5, 8,  5),
    vec4( 8, -5, 8,  5));

const vec4 door[] = vec4[](
    vec4(-3, -5, -3, -3),
    vec4(-8, 0, -5, 0),
    vec4(2, -3, 4, -3),
    vec4(-3, 2, -3, 5),
    vec4(0, -1, 0, 0),
    vec4(5, 0, 6, 0));

const ivec2 edge[door.length()] = ivec2[](
    ivec2(0, 1),
    ivec2(0, 2),
    ivec2(1, 4),
    ivec2(2, 3),
    ivec2(3, 4),
    ivec2(4, 5));

// Find convex set that contains q.
int room(vec2 q)
{
    float x = q.x, y = q.y;
    if (x < -8. || 8. < x || y < -5. || 5. < y) return -1;
    if (x < -3.) return y < 0. ? 0 : 2;
    if (y < -3.) return 1;
    if (x < 0.) return 3;
    if (y < 0.) return 4;
    return 5;
}

// Is door i adjacent to (src, oi)?
bool fw(int src, int i, out int oi)
{
    ivec2 e = edge[i].x == src ? edge[i] : edge[i].yx;
    oi = e.y;
    return e.x == src;
}

#define Thread vec4
const Thread init = Thread(1e9, 0, 0, 1e9);
const Thread inf = Thread(1e9, 1e9, 0, 1e9);

#if algorithm == 0
    // Iterate over all paths crossing at most 4 doors, use dynamic programming to find shortest instace of each path.

    void check(inout Thread RS, Thread rs)
    {
        if (rs.y < RS.y)
            RS = Thread(rs.xyz, min(rs.w, RS.y));
        else
            RS.w = min(rs.y, RS.w);
    }

    void check3(inout Thread rsb, Thread rsa, vec2 a, vec2 b)
    {
        rsa.y += length(a - b);
        if (rsa.y < rsb.y)
            rsb = Thread(min(rsa.x, line(a, b)), rsa.y, rsa.z + 1., 1e9);
    }
    void check3(inout Thread rsb, Thread rsa, vec2 a, vec4 i, vec2 b)
    {
        if (ll(a, b, i))
            check3(rsb, rsa, a, b);
    }
    void check3(inout Thread rsb, Thread rsa, vec2 a, vec4 i, vec4 j, vec2 b)
    {
        if (ll(a, b, i) && ll(a, b, j))
            check3(rsb, rsa, a, b);
    }
    void check3(inout Thread rsb, Thread rsa, vec2 a, vec4 i, vec4 j, vec4 k, vec2 b)
    {
        if (ll(a, b, i) && ll(a, b, j) && ll(a, b, k))
            check3(rsb, rsa, a, b);
    }
    void check3(inout Thread rsb, Thread rsa, vec2 a, vec4 i, vec4 j, vec4 k, vec4 l, vec2 b)
    {
        if (ll(a, b, i) && ll(a, b, j) && ll(a, b, k) && ll(a, b, l))
            check3(rsb, rsa, a, b);
    }


    vec2 pass(int i, float f)
    {
        return mix(door[i].xy, door[i].zw, f);
    }

    // pullMix
    // pullOptimal
    #define pullAlg pullOptimal

    Thread pullMix(vec2 a, int i, int j, int k, int l, vec2 b)
    {
        vec4 f = vec4(.5);
        vec2 x = pass(i, f.x), y = pass(j, f.y), z = pass(k, f.z), w = pass(l, f.w);
        float r = min(min(min(min(line(a, x), line(x, y)), line(y, z)), line(z, w)), line(w, b));
        float s = length(a - x) + length(x - y) + length(y - z) + length(z - w) + length(w - b);
        return Thread(r, s, 0, 1e9);
    }

    Thread pullOptimal(vec2 a, int i, int j, int k, int l, vec2 b)
    {
        Thread rs[9], rsa = init;
        foreach (i, rs) rs[i] = inf;

        // a .. i
        check3(rs[0], rsa, a, door[i].xy);
        check3(rs[1], rsa, a, door[i].zw);

        if (i == j)
        {
            // i .. b
            check3(rs[8], rs[0], door[i].xy, b);
            check3(rs[8], rs[1], door[i].zw, b);
            // a .. b (via i)
            check3(rs[8], rsa, a, door[i], b);
        } else {
            // i .. j
            check3(rs[2], rs[0], door[i].xy, door[j].xy);
            check3(rs[3], rs[0], door[i].xy, door[j].zw);
            check3(rs[2], rs[1], door[i].zw, door[j].xy);
            check3(rs[3], rs[1], door[i].zw, door[j].zw);
            // a .. j (via i)
            check3(rs[2], rsa, a, door[i], door[j].xy);
            check3(rs[3], rsa, a, door[i], door[j].zw);

            if (j == k)
            {
                // j .. b
                check3(rs[8], rs[2], door[j].xy, b);
                check3(rs[8], rs[3], door[j].zw, b);
                // i .. b (via j)
                check3(rs[8], rs[0], door[i].xy, door[j], b);
                check3(rs[8], rs[1], door[i].zw, door[j], b);
                // a .. b (via i, j)
                check3(rs[8], rsa, a, door[i], door[j], b);
            } else {
                // j .. k
                check3(rs[4], rs[2], door[j].xy, door[k].xy);
                check3(rs[5], rs[2], door[j].xy, door[k].zw);
                check3(rs[4], rs[3], door[j].zw, door[k].xy);
                check3(rs[5], rs[3], door[j].zw, door[k].zw);
                // i .. k (via j)
                check3(rs[4], rs[0], door[i].xy, door[j], door[k].xy);
                check3(rs[5], rs[0], door[i].xy, door[j], door[k].zw);
                check3(rs[4], rs[1], door[i].zw, door[j], door[k].xy);
                check3(rs[5], rs[1], door[i].zw, door[j], door[k].zw);
                // a .. k (via i, j)
                check3(rs[4], rsa, a, door[i], door[j], door[k].xy);
                check3(rs[5], rsa, a, door[i], door[j], door[k].zw);

                if (k == l)
                {
                    // k .. b
                    check3(rs[8], rs[4], door[k].xy, b);
                    check3(rs[8], rs[5], door[k].zw, b);
                    // j .. b (via k)
                    check3(rs[8], rs[2], door[j].xy, door[k], b);
                    check3(rs[8], rs[3], door[j].zw, door[k], b);
                    // i .. b (via j, k)
                    check3(rs[8], rs[0], door[i].xy, door[j], door[k], b);
                    check3(rs[8], rs[1], door[i].zw, door[j], door[k], b);
                    // a .. b (via i, j, k)
                    check3(rs[8], rsa, a, door[i], door[j], door[k], b);
                } else {
                    // k .. l
                    check3(rs[6], rs[4], door[k].xy, door[l].xy);
                    check3(rs[7], rs[4], door[k].xy, door[l].zw);
                    check3(rs[6], rs[5], door[k].zw, door[l].xy);
                    check3(rs[7], rs[5], door[k].zw, door[l].zw);
                    // j .. l (via k)
                    check3(rs[6], rs[2], door[j].xy, door[k], door[l].xy);
                    check3(rs[7], rs[2], door[j].xy, door[k], door[l].zw);
                    check3(rs[6], rs[3], door[j].zw, door[k], door[l].xy);
                    check3(rs[7], rs[3], door[j].zw, door[k], door[l].zw);
                    // i .. l (via j, k)
                    check3(rs[6], rs[0], door[i].xy, door[j], door[k], door[l].xy);
                    check3(rs[7], rs[0], door[i].xy, door[j], door[k], door[l].zw);
                    check3(rs[6], rs[1], door[i].zw, door[j], door[k], door[l].xy);
                    check3(rs[7], rs[1], door[i].zw, door[j], door[k], door[l].zw);
                    // a .. l (via i, j, k)
                    check3(rs[6], rsa, a, door[i], door[j], door[k], door[l].xy);
                    check3(rs[7], rsa, a, door[i], door[j], door[k], door[l].zw);

                    // l .. b
                    check3(rs[8], rs[6], door[l].xy, b);
                    check3(rs[8], rs[7], door[l].zw, b);
                    // k .. b (via l)
                    check3(rs[8], rs[4], door[k].xy, door[l], b);
                    check3(rs[8], rs[5], door[k].zw, door[l], b);
                    // j .. b (via k, l)
                    check3(rs[8], rs[2], door[j].xy, door[k], door[l], b);
                    check3(rs[8], rs[3], door[j].zw, door[k], door[l], b);
                    // i .. b (via j, k, l)
                    check3(rs[8], rs[0], door[i].xy, door[j], door[k], door[l], b);
                    check3(rs[8], rs[1], door[i].zw, door[j], door[k], door[l], b);
                    // a .. b (via i, j, k, l)
                    check3(rs[8], rsa, a, door[i], door[j], door[k], door[l], b);
                }
            }
        }

        return rs[8];
    }

    Thread path(vec2 a, vec2 b)
    {
        Thread rs = inf;
        int src = room(a), dst = room(b);
        if (src < 0 || dst < 0)
            return rs;
        int ei, ej, ek, el;
        if (src == dst)
            check(rs, Thread(line(a, b), length(a - b), 1, 1e9));
        foreach (i, edge) if (fw(src, i, ei))
        {
            if (ei == dst)
                check(rs, pullAlg(a, i, i, i, i, b));
            foreach (j, edge) if (fw(ei, j, ej) && ej != src && ej != ei)
            {
                if (ej == dst)
                    check(rs, pullAlg(a, i, j, j, j, b));
                foreach (k, edge) if (fw(ej, k, ek) && ek != src && ek != ei && ek != ej)
                {
                    if (ek == dst)
                        check(rs, pullAlg(a, i, j, k, k, b));
                    foreach (l, edge) if (fw(ek, l, el) && el != src && el != ei && el != ej && el != ek)
                    {
                        if (el == dst)
                            check(rs, pullAlg(a, i, j, k, l, b));
        }}}}
        return rs;
    }
#endif // algorithm == 0

#if algorithm == 1
    // Shortest path using Bellman-Ford (start, end and door edges are nodes, open paths are edges).

    int ra;
    vec2 rs[2 + 2 * door.length()], a;

    void check(int o, int p, vec2 a, vec2 b)
    {
        float s = rs[p].y + length(a - b);
        if (s < rs[o].y)
            rs[o] = vec2(min(rs[p].x, line(a, b)), s);
    }
    void check(int o, int p, vec2 a, int i, vec2 b)
    {
        if (ll(a, b, door[i]))
            check(o, p, a, b);
    }
    void check(int o, int p, vec2 a, int i, int j, vec2 b)
    {
        if (ll(a, b, door[j]))
            check(o, p, a, i, b);
    }
    void check(int o, int p, vec2 a, int i, int j, int k, vec2 b)
    {
        if (ll(a, b, door[k]))
            check(o, p, a, i, j, b);
    }

    void check(int o, int rb, vec2 b)
    {
        int oi, oj, ok;
        if (ra == rb) check(o, 0, a, b);
        foreach (i, door) if (fw(rb, i, oi))
        {
            if (ra == oi) check(o, 0, a, i, b);
            check(o, 2 + 2 * i, door[i].xy, b);
            check(o, 3 + 2 * i, door[i].zw, b);
            foreach (j, door) if (i != j && fw(oi, j, oj))
            {
                if (ra == oj) check(o, 0, a, j, i, b);
                check(o, 2 + 2 * j, door[j].xy, i, b);
                check(o, 3 + 2 * j, door[j].zw, i, b);
                foreach (k, door) if (j != k && fw(oj, k, ok))
                {
                    if (ra == ok) check(o, 0, a, k, j, i, b);
                    check(o, 2 + 2 * k, door[k].xy, j, i, b);
                    check(o, 3 + 2 * k, door[k].zw, j, i, b);
                }
            }
        }
    }

    Thread path(vec2 _a, vec2 b)
    {
        a = _a;
        ra = room(a);
        int rb = room(b);
        if (ra < 0 || rb < 0)
            return vec2(1e9);
        foreach (i, rs)
            rs[i] = vec2(1e9, 1e9);
        rs[0] = vec2(1e9, 0);
        for (int n=0 ; n<5 ; n++)
        {
            check(1, rb, b);
            foreach (i, door)
            {
                check(2 + 2 * i, edge[i].x, door[i].xy);
                check(2 + 2 * i, edge[i].y, door[i].xy);
                check(3 + 2 * i, edge[i].x, door[i].zw);
                check(3 + 2 * i, edge[i].y, door[i].zw);
            }
        }
        return Thread(rs[1], 0);
    }
#endif // algorithm == 1

void demo()
{
    float t = time / 10.;
    mouse.xy = sin(t * vec2(3, 5) + vec2(2, 3)) * vec2(7, 4);
    mouse.zw = sin(t * vec2(2, 1) + vec2(3, 5)) * vec2(7, 4);
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    time = iTime;
    f = iResolution.y / 11.;
    uv = (fragCoord - iResolution.xy / 2.) / f;

    mouse = (abs(iMouse) - iResolution.xyxy / 2.) / f;
    //mouse.zw = vec2(-4, 4);
    if (iMouse.x < 5.)
        demo();

    Thread rs = path(mouse.xy, uv);
    if (rs.y < 1e9)
    {
        vec3 c = vec3(.5 + .2 * cos(-10.*rs.y));
        int i = int(rs.z);
        if (isactive(iChannel3, keyF) && i >= 2)
            c = mix(c, vec3[](vec3(0,.2,1), vec3(1,.2,0), vec3(0,.5,0), vec3(1,0,0))[i - 2], .5);
        blend(c, 0.);
        if (isactive(iChannel3, keyM))
            blend(vec3(1,0,1), (rs.w - rs.y)*f - .5);
    }
    blend(vec4(0,0,0,.5), abs(uv.y - round(uv.y))*f);
    blend(vec4(0,0,0,.5), abs(uv.x - round(uv.x))*f);
    foreach (i, door)
        blend(vec3(1,.2,0), line(door[i].xy, door[i].zw)*f - .5);
    foreach (i, wall)
        blend(vec3(0), line(wall[i].xy, wall[i].zw)*f - .5);
    blend(vec3(1,0,0), path(mouse.xy, mouse.zw).x*f - .5);
    //blend(vec3(1,0,0), line(mouse.xy, mouse.zw)*f - .5);
    blend(vec3(0,.2,1), ping(mouse.zw, true));
    blend(vec3(0,.5,0), ping(mouse.xy, false));
    fragColor = sqrt(C);
}

#define foreach(i, a) for (int i=0 ; i<a.length() ; i++)

float f, time;
vec2 uv;
vec4 mouse, C = vec4(1);

const int keyF = 0x46, keyM = 0x4d;

bool down(sampler2D iKeyboard, int key)
{
    return texelFetch(iKeyboard, ivec2(key, 0), 0).x > 0.;
}

bool pressed(sampler2D iKeyboard, int key)
{
    return texelFetch(iKeyboard, ivec2(key, 1), 0).x > 0.;
}

bool isactive(sampler2D iKeyboard, int key)
{
    return texelFetch(iKeyboard, ivec2(key, 2), 0).x > 0.;
}

void blend(vec3 c, float r)
{
    C = mix(vec4(c, 1), C, clamp(r, 0., 1.));
}
void blend(vec4 c, float r)
{
    c *= clamp(1. - r, 0., 1.);
    C = C * (1. - c.w) + c;
}

vec2 R(float a)
{
    return vec2(cos(a), sin(a));
}

float arc(float c, float a, float r)
{
    vec2 q = uv * mat2(R(c), -sin(c), cos(c));
    q.y = abs(q.y);
    if (atan(q.y ,q.x) < a)
        return length(R(a) * r - q);
    return length(q) - r;
}

float line(vec2 a, vec2 b)
{
    b -= a;
    a = uv - a;
    return length(a - b * clamp(dot(a, b) / dot(b, b), 0., 1.));
}

float ping(vec2 q, bool inv)
{
    float r = length(q - uv) * f;
    float t = fract(time / 4.);
    if (inv) t = 1. - t;
    return min(r - 5. + .2 * cos(t*6.), abs(r - mix(5., 25., t*t)) + 1. - min(t*2., (1.-t)*3.));
}

vec2 N(vec2 a) { return vec2(a.y, -a.x); }

float crs(vec2 a, vec2 b) { return dot(a, N(b)); }

vec2 llx(vec2 a, vec2 b, vec2 p, vec2 q)
{
    b -= a;
    q -= p;
    vec3 ab = cross(vec3(a, 1), vec3(b, 0));
    vec3 pq = cross(vec3(p, 1), vec3(q, 0));
    vec3 x = cross(ab, pq);
    if (abs(x.z) < 1e-8)
        return vec2(-1);
    x /= x.z;
    return vec2(dot(x.xy - a, b) / dot(b, b), dot(x.xy - p, q) / dot(q, q));
}

// Do segments ab and pq intersect?
bool ll(vec2 a, vec2 b, vec4 pq)
{
    vec2 t = llx(a, b, pq.xy, pq.zw);
    return 0. <= t.x && t.x <= 1. && 0. <= t.y && t.y <= 1.;
}
